        setValue(L.DESC_COMMAND_REVALIDATE_PART_PARAM, "La partie dont le résumé est revalidé (son identifiant) ; tous les résumés de la branche active si omis");
        setValue(L.DESC_COMMAND_BOOK_NAME_PARAM, "Le nouveau nom du livre");
        setValue(L.DESC_COMMAND_BOOK_DESCRIPTION_PARAM, "La nouvelle description du livre");
        setValue(L.DESC_COMMAND_BOOK_POV_PARAM, "Le point de vue narratif du livre, un texte libre comme \"Troisième personne limitée\"");
        setValue(L.DESC_COMMAND_BOOK_TENSE_PARAM, "Le temps narratif du livre, un texte libre comme \"Passé\"");
        setValue(L.DESC_COMMAND_BOOK_STYLE_PARAM, "Le style dans lequel le livre est écrit, un texte libre");
        setValue(L.DESC_COMMAND_BOOK_LANGUAGE_PARAM, "La langue du livre : son nom (anglais) ou son code ISO 639-1 (en)");
        setValue(L.DESC_COMMAND_BOOK_TEMPLATE_PARAM, "Le modèle principal du livre, le prompt système de chaque génération (un modèle Handlebars)");
        setValue(L.DESC_COMMAND_BOOK_USER_PROMPT_PARAM, "Le modèle du prompt utilisateur d'un tour");
        setValue(L.DESC_COMMAND_BOOK_SUMMARY_PROMPT_PARAM, "Le modèle du prompt qui fait un résumé");
        setValue(L.DESC_COMMAND_BOOK_META_SUMMARY_PROMPT_PARAM, "Le modèle du prompt qui fait un méta-résumé");
        setValue(L.DESC_COMMAND_TAGS_ADD_PARAM, "Mots-clés à ajouter au livre, séparés par des virgules");
        setValue(L.DESC_COMMAND_TAGS_REMOVE_PARAM, "Mots-clés à retirer du livre, séparés par des virgules");
        setValue(L.DESC_COMMAND_CREATE_PART, "Écrit une nouvelle partie de l'histoire. Paramètres : text, parent (identifiant), instructions, scene, pov, present.");
        setValue(L.DESC_COMMAND_CREATE_PART_LLM, "Ajoute à l'histoire une nouvelle partie avec le texte donné : après la partie `parent` (son identifiant), ou après la dernière partie de la branche active quand `parent` est omis (la première partie d'un livre vide). Une partie qui continue une partie ayant déjà une suite commence une nouvelle branche. La nouvelle partie devient la fin de la branche active. Enregistre éventuellement l'entrée de tour (instructions, scene, pov, present) qu'elle représente. Utilisez-la pour écrire du texte vous-même ; pour le faire écrire par le modèle, utilisez next. Modifie le livre. Renvoie l'identifiant de la nouvelle partie.");
        setValue(L.DESC_COMMAND_CREATE_PART_RETURN, "JSON avec la nouvelle partie (handle, position, mots, jetons) et la longueur de la branche");
        setValue(L.DESC_COMMAND_BRANCH_PART, "Fait une copie d'une partie à côté d'elle comme nouvelle branche. Paramètres : part (identifiant).");
        setValue(L.DESC_COMMAND_BRANCH_PART_LLM, "Copie la partie (et son résumé) comme sa sœur, une nouvelle variante qui commence une nouvelle branche, et fait de la copie la fin de la branche active. Les parties qui suivent l'original restent avec l'original. Utilisez-la pour essayer une autre version d'une partie sans perdre la première. La partie se désigne par son identifiant. Modifie le livre. Renvoie l'identifiant de la copie.");
        setValue(L.DESC_COMMAND_BRANCH_PART_RETURN, "JSON avec la nouvelle partie (handle, position, mots, jetons) et l'identifiant dont elle a été copiée");
        setValue(L.DESC_COMMAND_DELETE_PART, "Supprime une partie de l'histoire ; les parties qui la suivent restent. Paramètres : part (identifiant).");
        setValue(L.DESC_COMMAND_DELETE_PART_LLM, "Supprime une partie de l'histoire et son résumé. Les parties qui la suivaient restent et continuent son parent, tout ce qui suit remonte donc d'une position. Les résumés des parties suivantes peuvent devenir obsolètes (la réponse les liste). La partie se désigne par son identifiant. Modifie le livre ; l'utilisateur doit confirmer, un agent est couvert par son mode destructif.");
        setValue(L.DESC_COMMAND_DELETE_PART_RETURN, "JSON avec l'identifiant de la partie supprimée, combien de parties la suivaient, la partie active maintenant et les résumés devenus obsolètes");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH, "Fait de la branche passant par une partie la branche active. Paramètres : part (identifiant).");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH_LLM, "Fait de la branche qui passe par la partie la branche active du livre : sa fin est la suite la plus récente sous la partie. Ce que fait le choix d'une autre variante. La partie se désigne par son identifiant (voir list-swipes et list-branches). Change les parties sur lesquelles travaillent les commandes sans branche, et ce que continue la prochaine génération. Modifie le livre.");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH_RETURN, "JSON avec la partie, l'identifiant de la fin de la branche et sa longueur");
        setValue(L.DESC_COMMAND_SET_SUMMARY, "Remplace le texte du résumé d'une partie. Paramètres : part (identifiant), text.");
        setValue(L.DESC_COMMAND_SET_SUMMARY_LLM, "Remplace le texte du résumé posé sur une partie de l'histoire (la partie doit en avoir un). Le résumé représente les parties jusqu'à sa partie ; ses jetons sont recomptés. Un méta-résumé au-dessus qui l'inclut peut devenir obsolète (la réponse les liste). La partie se désigne par son identifiant. Modifie le livre.");
        setValue(L.DESC_COMMAND_SET_SUMMARY_RETURN, "JSON avec la partie, les jetons du résumé et les résumés devenus obsolètes");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY, "Retire le résumé d'une partie. Paramètres : part (identifiant), unwind.");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY_LLM, "Retire le résumé posé sur une partie de l'histoire, la génération réutilise donc les parties elles-mêmes à sa place. Avec `unwind`, un méta-résumé est remplacé par le résumé qu'il avait remplacé. La partie se désigne par son identifiant. Modifie le livre ; l'utilisateur doit confirmer, un agent est couvert par son mode destructif.");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY_RETURN, "JSON avec la partie et si elle a maintenant un résumé");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES, "Déclare que les résumés obsolètes décrivent toujours l'histoire. Paramètres : part (identifiant).");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES_LLM, "Marque à nouveau comme valides les résumés devenus obsolètes par une modification : l'empreinte de l'histoire qu'ils décrivent est recalculée. Utilisez-la seulement après avoir vérifié que ce que dit le résumé reste vrai après la modification (une faute de frappe corrigée, un nom changé) ; un résumé qui décrit des événements qui ont changé doit être refait avec regenerate-summary. Sans `part`, tous les résumés de la branche active ; avec `part`, seulement le résumé de cette partie (son identifiant). Modifie le livre.");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES_RETURN, "JSON avec le nombre de résumés revalidés et leurs parties");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO, "Modifie le nom, la description, le point de vue, le temps, le style ou la langue du livre. Paramètres : name, description, pov, tense, style, language.");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO_LLM, "Modifie les paramètres descriptifs du livre : son nom, sa description, son point de vue narratif, son temps, son style et sa langue. Seules les valeurs données sont modifiées, le reste demeure (un texte vide efface un champ, le nom ne peut pas être vide). La langue, le point de vue, le temps et le style sont utilisés dans les prompts de la génération. Le modèle, le lorebook et les modèles de prompt ne sont pas modifiés ici. Modifie le livre.");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO_RETURN, "JSON avec les paramètres du livre après la modification");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS, "Remplace les modèles de prompt du livre. Paramètres : template, userPrompt, summaryPrompt, metaSummaryPrompt.");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS_LLM, "Remplace les modèles de prompt avec lesquels se fait la génération du livre : le modèle principal (le prompt système), le prompt utilisateur d'un tour, et les prompts du résumé et du méta-résumé. Seuls les modèles donnés sont modifiés. Chacun est d'abord vérifié : un modèle invalide est refusé et rien n'est modifié, un modèle qui utilise des noms inexistants est enregistré et la réponse dit lesquels. Toutes les générations suivantes du livre utilisent ces modèles, un mauvais modèle gâche donc l'histoire : ne les modifiez que sur demande. Modifie le livre ; l'utilisateur doit confirmer, un agent est couvert par son mode destructif.");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS_RETURN, "JSON avec les modèles modifiés et les avertissements sur les noms inexistants");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS, "Ajoute des mots-clés au livre ou en retire. Paramètres : add, remove (séparés par des virgules).");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS_LLM, "Ajoute des mots-clés au livre et en retire ; les deux sont des listes séparées par des virgules, l'une ou l'autre peut être omise. Les mots-clés du livre décident quelles entrées de lorebook limitées à des mots-clés sont utilisées. Un mot-clé inexistant est créé. Modifie le livre.");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS_RETURN, "JSON avec les mots-clés du livre après la modification");
        setValue(L.DESC_COMMAND_LORE_ENTRY_HANDLE_PARAM, "L'identifiant de l'entrée (le \"handle\" de list-lore-entries) ; un numéro n'est pas accepté");
        setValue(L.DESC_COMMAND_LOREBOOK_HANDLE_PARAM, "L'identifiant du lorebook (le \"handle\" de list-lorebooks) ; un numéro n'est pas accepté");
        setValue(L.DESC_COMMAND_TARGET_LOREBOOK_PARAM, "L'identifiant du lorebook où se trouve l'entrée ; le lorebook racine si omis");
        setValue(L.DESC_COMMAND_LORE_NAME_PARAM, "Le nom de l'entrée");
        setValue(L.DESC_COMMAND_LORE_PAYLOAD_PARAM, "Le texte de l'entrée, un modèle Handlebars ; il entre dans le prompt quand l'entrée est utilisée");
        setValue(L.DESC_COMMAND_LORE_COMMENT_PARAM, "Une note sur l'entrée pour l'auteur, elle n'est pas mise dans le prompt");
        setValue(L.DESC_COMMAND_LORE_ENABLED_PARAM, "Si l'entrée est utilisée, true si omis");
        setValue(L.DESC_COMMAND_LORE_ORDER_PARAM, "La place de l'entrée parmi les entrées utilisées de tous les lorebooks : plus bas vient en premier, à ordre égal par date de création ; 100 si omis. get-lore-entry et list-lore-entries montrent l'ordre des autres");
        setValue(L.DESC_COMMAND_LORE_KEYS_PARAM, "Les mots (une liste séparée par des virgules, comme \"Prénom, Nom\") ou l'expression régulière dans le texte du tour qui font utiliser l'entrée ; vide pour une entrée toujours utilisée");
        setValue(L.DESC_COMMAND_LORE_FILTERING_MODE_PARAM, "Comment les clés sont comparées : KEYWORDS_OR (les clés sont une liste séparée par des virgules, n'importe laquelle dans le texte fait utiliser l'entrée), KEYWORDS_AND (toutes doivent être dans le texte), TEXT (les clés forment un seul texte) ou REGEX ; KEYWORDS_OR si omis à la création, inchangé à la mise à jour");
        setValue(L.DESC_COMMAND_LORE_INSERTION_MODE_PARAM, "Où va le texte : IN_LORE_BLOCK (dans le bloc de lore, dans l'ordre des entrées) ou BEFORE_USER_PROMPT (juste avant la requête, là où le modèle est le plus attentif ; pour ce qui doit influencer cette partie précise, avec parcimonie) ; IN_LORE_BLOCK si omis");
        setValue(L.DESC_COMMAND_LORE_TAGS_PARAM, "Mots-clés de l'entrée, séparés par des virgules : l'entrée n'est utilisée que dans les livres qui en ont un");
        setValue(L.DESC_COMMAND_LORE_TAGS_ADD_PARAM, "Mots-clés à ajouter à l'entrée, séparés par des virgules");
        setValue(L.DESC_COMMAND_LORE_TAGS_REMOVE_PARAM, "Mots-clés à retirer de l'entrée, séparés par des virgules");
        setValue(L.DESC_COMMAND_LORE_NEGATIVE_ADD_PARAM, "Mots-clés négatifs à ajouter, séparés par des virgules : l'entrée n'est pas utilisée dans les livres qui en ont un");
        setValue(L.DESC_COMMAND_LORE_NEGATIVE_REMOVE_PARAM, "Mots-clés négatifs à retirer de l'entrée, séparés par des virgules");
        setValue(L.DESC_COMMAND_LOREBOOK_NAME_PARAM, "Le nom du lorebook");
        setValue(L.DESC_COMMAND_LOREBOOK_ENABLED_PARAM, "Si le lorebook est utilisé");
        setValue(L.DESC_COMMAND_PARENT_LOREBOOK_PARAM, "L'identifiant du lorebook qui reçoit le nouveau comme sous-livre ; le lorebook racine si omis");
        setValue(L.DESC_COMMAND_SUBBOOK_PARAM, "L'identifiant du lorebook qui est (ou cesse d'être) un sous-livre");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY, "Ajoute une entrée à un lorebook. Paramètres : name, payload, lorebook (identifiant), comment, enabled, order, keys, filteringMode, insertionMode, tags.");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_LLM, "Ajoute une nouvelle entrée à un lorebook du livre (le lorebook racine quand `lorebook` est omis). `payload` est le texte qui entre dans le prompt, un modèle Handlebars. Une entrée sans `keys` est toujours utilisée, sinon elle l'est quand les clés sont dans le texte du tour : `keys` est une liste de mots séparés par des virgules (par exemple \"Anna, Novak\"), l'entrée est utilisée quand n'importe lequel est présent (filteringMode KEYWORDS_OR, par défaut) ou quand tous le sont (KEYWORDS_AND) ; filteringMode TEXT prend tout `keys` comme un seul texte et REGEX comme une expression régulière. Un problème du modèle ou de l'expression régulière n'empêche pas l'enregistrement, il est signalé dans la réponse : corrigez-le avec update-lore-entry. `order` (plus bas vient en premier, 100 si omis) place l'entrée plus tôt ou plus tard parmi les entrées utilisées : lisez l'`order` des autres avec list-lore-entries pour la placer entre elles. `insertionMode` BEFORE_USER_PROMPT déplace le texte du bloc de lore à juste avant la requête. Modifie le livre. Renvoie l'identifiant de l'entrée.");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_RETURN, "JSON avec l'entrée (handle, name) et les problèmes de son texte ou de son filtre, s'il y en a");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY, "Modifie les champs d'une entrée de lorebook. Paramètres : entry (identifiant), name, payload, comment, enabled, order, keys, filteringMode, insertionMode.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_LLM, "Modifie l'entrée ayant l'identifiant donné : seuls les champs donnés sont modifiés. Pour modifier un morceau d'un long texte, lisez-le avec get-lore-entry et donnez tout le nouveau `payload`. Un problème du modèle ou de l'expression régulière n'empêche pas l'enregistrement, il est signalé dans la réponse. `order` et `insertionMode` déplacent l'entrée dans le prompt (voir create-lore-entry). Pour modifier les mots-clés utilisez set-lore-entry-tags, pour la déplacer move-lore-entry. Modifie le livre.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_RETURN, "JSON avec l'entrée (handle, name) et les problèmes de son texte ou de son filtre, s'il y en a");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY, "Supprime une entrée d'un lorebook. Paramètres : entry (identifiant).");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_LLM, "Supprime l'entrée ayant l'identifiant donné de son lorebook. Les numéros des entrées qui la suivent dans le lorebook changent, pas les identifiants. Modifie le livre ; l'utilisateur doit confirmer, un agent est couvert par son mode destructif.");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_RETURN, "JSON avec l'identifiant et le nom de l'entrée supprimée");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY, "Déplace une entrée vers un autre lorebook du livre. Paramètres : entry (identifiant), lorebook (identifiant).");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_LLM, "Déplace l'entrée vers un autre lorebook du livre (le lorebook racine ou l'un de ses sous-livres). Ses champs et mots-clés restent. Modifie le livre.");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_RETURN, "JSON avec l'entrée (handle, name) et les problèmes de son texte ou de son filtre, s'il y en a");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS, "Ajoute et retire les mots-clés et les mots-clés négatifs d'une entrée. Paramètres : entry (identifiant), add, remove, addNegative, removeNegative (séparés par des virgules).");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_LLM, "Modifie les mots-clés de l'entrée ayant l'identifiant donné ; chaque liste est séparée par des virgules et peut être omise. Une entrée avec des mots-clés n'est utilisée que dans les livres qui en ont un, une entrée avec des mots-clés négatifs n'est pas utilisée dans les livres qui en ont un (voir les mots-clés du livre, set-book-tags). Un mot-clé inexistant est créé. Modifie le livre.");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_RETURN, "JSON avec les mots-clés et les mots-clés négatifs de l'entrée après la modification");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK, "Crée un nouveau lorebook, sous-livre d'un autre. Paramètres : name, parent (identifiant).");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_LLM, "Crée un nouveau lorebook vide et l'ajoute comme sous-livre du lorebook `parent` (le lorebook racine si omis), ses entrées sont donc utilisées dans le livre. Modifie le livre. Renvoie l'identifiant du nouveau lorebook.");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_RETURN, "JSON avec le nouveau lorebook (handle, number, name)");
        setValue(L.DESC_COMMAND_SET_LOREBOOK, "Renomme un lorebook ou l'active/désactive. Paramètres : lorebook (identifiant), name, enabled.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_LLM, "Modifie le nom d'un lorebook du livre, ou s'il est utilisé : les entrées d'un lorebook désactivé ne sont pas utilisées. Seules les valeurs données sont modifiées. Modifie le livre.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_RETURN, "JSON avec le lorebook (handle, number, name, enabled)");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK, "Fait d'un lorebook du livre un sous-livre d'un autre. Paramètres : lorebook (identifiant), subbook (identifiant).");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_LLM, "Fait du lorebook `subbook` un sous-livre du lorebook `lorebook`, ses entrées sont donc utilisées partout où le lorebook l'est. Les deux doivent être des lorebooks de ce livre ; un lorebook ne peut pas se contenir lui-même, directement ou via ses sous-livres (c'est refusé). Un lorebook supprimé ou retiré de son parent plus tôt dans cette exécution peut être désigné par son identifiant comme `subbook` : l'ajouter le ramène, avec ses entrées. Modifie le livre.");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_RETURN, "JSON avec le lorebook et ses sous-livres");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK, "Fait qu'un lorebook cesse d'être un sous-livre d'un autre. Paramètres : lorebook (identifiant), subbook (identifiant).");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_LLM, "Retire le lorebook `subbook` des sous-livres du lorebook `lorebook` ; rien ne se passe s'il n'en fait pas partie. Le lorebook n'est pas supprimé, mais quand aucun autre lorebook ne l'a comme sous-livre, ses entrées ne sont plus utilisées dans le livre ; vous pouvez toujours le désigner par son identifiant et l'ajouter à nouveau avec add-subbook. Modifie le livre.");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_RETURN, "JSON avec le lorebook et ses sous-livres");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK, "Supprime un lorebook avec ses entrées. Paramètres : lorebook (identifiant).");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_LLM, "Supprime un lorebook du livre avec toutes ses entrées, et le retire des sous-livres des lorebooks qui l'avaient. Il est seulement marqué comme supprimé : add-subbook avec son identifiant le ramène avec ses entrées. Le lorebook racine du livre ne peut pas être supprimé. Modifie le livre ; l'utilisateur doit confirmer, un agent est couvert par son mode destructif.");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_RETURN, "JSON avec l'identifiant et le nom du lorebook supprimé et le nombre d'entrées qu'il avait");
        setValue(L.DESC_COMMAND_MAX_HITS_PARAM, "Refuser de remplacer quand il y a plus de correspondances que cela ; aucune limite si omis");
        setValue(L.DESC_COMMAND_DRY_RUN_PARAM, "Seulement compter les correspondances et en montrer quelques-unes, ne rien modifier ; false si omis");
        setValue(L.DESC_COMMAND_GEN_INSTRUCTIONS_PARAM, "Ce que la nouvelle partie doit faire ou contenir ; pour swipe et regenerate, les instructions à partir desquelles la partie a été faite si omis");
        setValue(L.DESC_COMMAND_GEN_SCENE_PARAM, "Le cadre de la scène du tour ; pour swipe et regenerate, celui à partir duquel la partie a été faite si omis");
        setValue(L.DESC_COMMAND_GEN_POV_PARAM, "Le personnage du point de vue du tour ; pour swipe et regenerate, celui à partir duquel la partie a été faite si omis");
        setValue(L.DESC_COMMAND_GEN_PRESENT_PARAM, "Les personnages présents dans le tour ; pour swipe et regenerate, ceux à partir desquels la partie a été faite si omis");
        setValue(L.DESC_COMMAND_AFTER_PART_PARAM, "La partie après laquelle continuer (son identifiant), qui devient d'abord la fin de la branche active ; la fin de la branche active si omis");
        setValue(L.DESC_COMMAND_GEN_PROFILE_PARAM, "Le rôle de l'un des profils de modèle de l'agent avec lequel écrire ; le profil principal si omis");
        setValue(L.DESC_COMMAND_GEN_PART_PARAM, "La partie à réécrire (son identifiant) ; elle doit être la dernière partie de sa branche. La fin de la branche active si omis");
        setValue(L.DESC_COMMAND_META_FROM_PARAM, "La partie la plus récente de la plage à fusionner (son identifiant) ; le méta-résumé s'y pose");
        setValue(L.DESC_COMMAND_META_TO_PARAM, "La partie la plus ancienne de la plage à fusionner (son identifiant)");
        setValue(L.DESC_COMMAND_NEXT, "Fait écrire au modèle la partie suivante de l'histoire. Paramètres : scene, pov, present, instructions, after (identifiant), profile.");
        setValue(L.DESC_COMMAND_NEXT_LLM, "Fait écrire au modèle la partie suivante de l'histoire après la fin de la branche active (ou après la partie `after`), comme le fait le bouton Nouveau tour : le prompt est construit à partir du livre (modèle, lore, résumés, l'histoire jusqu'ici) et de l'entrée de tour donnée ici. Lent et coûte des jetons du modèle du livre (ou du `profile` de l'agent) ; une seule génération d'un livre tourne à la fois, les autres attendent. La nouvelle partie devient la fin de la branche active. Renvoie l'identifiant de la nouvelle partie ; lisez-la avec get-part. Modifie le livre. Asynchrone.");
        setValue(L.DESC_COMMAND_NEXT_RETURN, "JSON avec la nouvelle partie (handle, position, mots, jetons, modèle) et les avertissements de la génération");
        setValue(L.DESC_COMMAND_SWIPE, "Fait écrire au modèle une autre version de la dernière partie, à côté de la première. Paramètres : part (identifiant), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_SWIPE_LLM, "Fait écrire au modèle une autre version d'une partie (une variante) : une nouvelle sœur de la partie faite à partir du même tour (ou de l'entrée de tour modifiée donnée ici), qui devient la fin de la branche active ; la première version reste comme une autre branche (voir list-swipes, switch-branch). La partie doit être la dernière partie de sa branche. Lent et coûte des jetons ; une seule génération d'un livre tourne à la fois. Renvoie l'identifiant de la nouvelle partie. Modifie le livre. Asynchrone.");
        setValue(L.DESC_COMMAND_SWIPE_RETURN, "JSON avec la nouvelle partie (handle, position, mots, jetons, modèle) et les avertissements de la génération");
        setValue(L.DESC_COMMAND_REGENERATE, "Fait réécrire au modèle la dernière partie, en remplaçant son texte. Paramètres : part (identifiant), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_REGENERATE_LLM, "Fait réécrire au modèle la dernière partie d'une branche et remplace le texte de la partie sur place (pour garder l'ancien, utilisez swipe). La partie doit être la dernière partie de sa branche. L'ancien texte est perdu, sauf si la génération échoue, auquel cas il reste. Lent et coûte des jetons ; une seule génération d'un livre tourne à la fois. Renvoie l'identifiant de la partie. Modifie le livre ; l'utilisateur doit confirmer, un agent est couvert par son mode destructif. Asynchrone.");
        setValue(L.DESC_COMMAND_REGENERATE_RETURN, "JSON avec la nouvelle partie (handle, position, mots, jetons, modèle) et les avertissements de la génération");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY, "Fait refaire au modèle le résumé qui se termine à une partie. Paramètres : part (identifiant).");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_LLM, "Fait écrire au modèle le résumé posé sur la partie (la tête d'un bloc de résumé) à partir des parties qu'il représente, et le met sur la partie à la place de l'ancien, de sorte qu'un résumé obsolète redevient valide. Lent et coûte des jetons du modèle du livre. La partie se désigne par son identifiant. Modifie le livre. Asynchrone.");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_RETURN, "JSON avec la partie, les jetons du nouveau résumé et le début de son texte");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY, "Fait fusionner au modèle les résumés d'une plage en un seul. Paramètres : from (identifiant), to (identifiant).");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_LLM, "Fait fusionner au modèle les résumés depuis la partie `from` (la plus récente) jusqu'à la partie `to` (la plus ancienne, arrondie à la fin de son bloc de résumé) en un seul méta-résumé posé sur `from`, qui prend la place du résumé qui s'y trouvait. Utilisez-le pour faire tenir une longue histoire dans le contexte. Les deux parties sont dans la même branche et ont des résumés. Lent et coûte des jetons du modèle du livre. Modifie le livre. Asynchrone.");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_RETURN, "JSON avec la partie, les jetons du méta-résumé et le début de son texte");
        setValue(L.DESC_COMMAND_INSERT_PART, "Insère une nouvelle partie de l'histoire entre deux parties ; les parties qui suivent restent. Paramètres : text, part (identifiant), before (true ou false).");
        setValue(L.DESC_COMMAND_INSERT_PART_LLM, "Insère une nouvelle partie avec le texte donné au milieu de l'histoire : juste après la partie `part` (son identifiant), ou juste avant quand `before` est true. Tout ce qui suivait cet endroit (toutes les branches) suit maintenant la nouvelle partie, aucune partie n'est supprimée ni réécrite, les identifiants, résumés et données des autres parties restent donc ; chaque partie sous la nouvelle descend d'une position. Utilisez-la au lieu de supprimer et recréer les parties en dessous. Les résumés qui couvrent l'endroit deviennent obsolètes (signalés ; revalidate-summaries ou regenerate-summary les corrigent). À la fin de la branche, c'est la même chose que create-part. Modifie le livre. Renvoie l'identifiant de la nouvelle partie.");
        setValue(L.DESC_COMMAND_INSERT_PART_RETURN, "JSON avec la nouvelle partie (handle, position, mots, jetons), combien de branches la continuent, la longueur de sa branche et les résumés devenus obsolètes");
        setValue(L.DESC_COMMAND_INSERT_ANCHOR_PARAM, "La partie à côté de laquelle la nouvelle est insérée (son identifiant) : après elle, ou avant quand before est true");
        setValue(L.DESC_COMMAND_INSERT_BEFORE_PARAM, "true pour insérer avant la partie au lieu d'après ; false si omis");
        setValue(L.DESC_TEMPLATE_PREVIOUS_STORY, "L'histoire avant la partie, autant de sa fin que possible (l'histoire plus ancienne est dans les résumés).");
        setValue(L.DESC_TEMPLATE_PART_TEXT, "Le texte de la partie en cours de réécriture.");
        setValue(L.DESC_TEMPLATE_FOLLOWING_STORY, "L'histoire après la partie, autant que possible.");
        setValue(L.DESC_TEMPLATE_REDRAFT_INSTRUCTIONS, "Ce que l'auteur veut changer dans la partie (vide s'il n'a pas donné d'instructions).");
        setValue(L.DESC_COMMAND_REDRAFT_PART, "Fait réécrire au modèle une partie de l'histoire d'après des instructions (n'importe quelle partie, pas seulement la dernière), en remplaçant son texte. Coûte des jetons.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_LLM, "Fait réécrire au modèle la partie `part` (son identifiant) et remplace son texte par le résultat ; la partie peut être n'importe où dans l'histoire. `instructions` est ce qui doit changer (\"ajoute plus de dialogue\", \"allonge le combat\", \"garde la fin\") ; sans cela, la partie est réécrite avec les mêmes événements. Le modèle voit la partie, l'histoire avant elle (l'histoire plus ancienne sous forme de résumés) et après elle, le lore avec lequel la partie a été écrite et les données de son tour. `prompt` est un prompt de réécriture à utiliser à la place de celui du livre (un modèle avec les variables text, redraftInstructions, previousStory, summaries, followingStory, backgroundLore, narrativePov, narrativeTense, style, povCharacter, sceneSetting, presentCharacters, instructions) ; `profile` un profil de modèle de l'agent avec lequel écrire au lieu du modèle de l'exécution ; `apply` à false renvoie seulement le texte réécrit et laisse la partie telle quelle (pour le regarder d'abord, puis replace-part-text). Remplace le texte, les résumés qui couvrent la partie deviennent donc obsolètes (signalés). Lent, coûte des jetons. Renvoie la partie et, avec apply à false, le texte.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_RETURN, "Objet JSON : l'identifiant, la position, les mots et les jetons de la partie, applied, le texte (le texte entier quand apply est false) et les résumés obsolètes");
        setValue(L.DESC_COMMAND_REDRAFT_INSTRUCTIONS_PARAM, "Ce qui doit changer dans la partie ; vide réécrit la partie avec les mêmes événements");
        setValue(L.DESC_COMMAND_REDRAFT_PROMPT_PARAM, "Un prompt de réécriture à utiliser à la place de celui du livre (un modèle) ; vide : celui du livre");
        setValue(L.DESC_COMMAND_REDRAFT_APPLY_PARAM, "false renvoie seulement le texte réécrit et ne modifie pas la partie ; true (par défaut) remplace le texte de la partie");
        setValue(L.DESC_COMMAND_ANNOTATION_PARAM, "Identifiant de l'annotation (le \"handle\" de list-annotations)");
        setValue(L.DESC_COMMAND_ANNOTATION_STATUS_FILTER_PARAM, "open (par défaut), resolved, dismissed, orphaned ou all");
        setValue(L.DESC_COMMAND_ANNOTATION_STATUS_PARAM, "resolved (par défaut), dismissed ou open");
        setValue(L.DESC_COMMAND_ANNOTATION_FILTER_PART_PARAM, "Seulement les annotations de cette partie : son identifiant, ou sa position dans la branche active (la première partie est 1). Toutes les parties si omis");
        setValue(L.DESC_COMMAND_ANNOTATION_TEXT_PARAM, "La note");
        setValue(L.DESC_COMMAND_ANNOTATION_QUOTE_PARAM, "Les mots du passage concerné par la note, copiés de la partie. Vide pour une note sur toute la partie");
        setValue(L.DESC_COMMAND_ANNOTATION_TYPE_PARAM, "Un mot libre pour le genre de note (continuité, style...), vide pour aucun");
        setValue(L.DESC_COMMAND_ANNOTATION_SEND_PARAM, "true pour transmettre la note au modèle avec la partie, false sinon");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS, "Liste les annotations (notes sur des passages) du livre ou d'une partie. Paramètres : status, part, offset, limit.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_LLM, "Liste les annotations du livre, des notes pour l'auteur posées sur un passage d'une partie (ou sur une partie entière). Chaque ligne a son \"handle\", l'identifiant de sa partie et la position de la partie quand elle est dans la branche active, le statut (open, resolved, dismissed, orphaned : le passage a disparu), la source (author, ai, agent, plugin), le type, le passage (décalages de début et de fin dans le texte de la partie et les mots cités) s'il y en a un, et la note. Le statut est open si omis, \"all\" les liste toutes. Une partie (son identifiant, ou sa position dans la branche active) limite la liste à elle. Lecture seule. Les options sont positionnelles et facultatives, dans l'ordre indiqué.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_RETURN, "JSON avec les annotations et la pagination");
        setValue(L.DESC_COMMAND_GET_ANNOTATION, "Affiche une annotation avec sa note et le passage concerné. Paramètre : annotation (identifiant).");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_LLM, "Une annotation en entier : la note, le statut, la source, le type, le passage cité avec un peu de texte avant et après, et sa place dans la partie. L'annotation se désigne par son identifiant (tiré de list-annotations). Lecture seule.");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_RETURN, "JSON avec l'annotation");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION, "Ajoute une note à un passage d'une partie. Paramètres : part (identifiant), text, quote, type.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_LLM, "Annote un passage d'une partie de l'histoire avec une note pour l'auteur. Le texte de l'histoire n'est pas modifié et la note n'est pas envoyée au modèle. Donnez les mots du passage comme quote, copiés lettre pour lettre (quelques mots suffisent s'ils n'apparaissent qu'une fois dans la partie) : la note se pose alors sur ce passage et le suit quand le texte est modifié. Sans quote, la note porte sur toute la partie ; une citation absente du texte fait aussi une note sur toute la partie, et la réponse le dit. Le type est un mot libre (continuité, style...). La partie se désigne par son identifiant. S'ajoute aux annotations du livre.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_RETURN, "JSON avec la nouvelle annotation");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION, "Modifie la note, le type ou l'indicateur d'envoi au prompt d'une annotation. Paramètres : annotation (identifiant), text, type, sendToPrompt.");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION_LLM, "Modifie une annotation : le texte de la note, son type, et si elle est transmise au modèle avec sa partie (sendToPrompt). Un texte ou un type vide garde l'actuel ; sendToPrompt omis garde l'indicateur. L'annotation se désigne par son identifiant (tiré de list-annotations). Le passage et le statut ne sont pas modifiés ici (voir reattach-annotation et resolve-annotation).");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION_RETURN, "JSON avec l'annotation");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION, "Définit le statut d'une annotation : resolved (par défaut), dismissed ou open. Paramètres : annotation (identifiant), status.");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_LLM, "Ferme une annotation comme résolue (le problème a été traité) ou écartée (ne vaut pas d'être traitée), ou la rouvre (open). Une annotation fermée quitte le texte et reste dans la liste. Résolue si le statut est omis. L'annotation se désigne par son identifiant (tiré de list-annotations).");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_RETURN, "JSON avec l'annotation");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION, "Rattache une annotation au passage qu'une citation trouve dans sa partie. Paramètres : annotation (identifiant), quote.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_LLM, "Déplace une annotation vers un autre passage de sa partie : le passage est trouvé par la citation, qui doit être copiée du texte de la partie. Une annotation orpheline (son passage a été supprimé) est rouverte. L'annotation se désigne par son identifiant (tiré de list-annotations). Sans citation, l'annotation porte sur toute la partie.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_RETURN, "JSON avec l'annotation");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION, "Supprime une annotation. Paramètre : annotation (identifiant).");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION_LLM, "Supprime une annotation (l'utilisateur peut la récupérer dans la corbeille). Pour fermer une annotation tout en la gardant dans la liste, utilisez resolve-annotation. L'annotation se désigne par son identifiant (tiré de list-annotations).");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION_RETURN, "JSON avec l'identifiant de l'annotation supprimée");
        setValue(L.DESC_TEMPLATE_ANNOTATIONS, "Les annotations ouvertes de la partie, une par ligne : le passage entre guillemets et la note (vide quand il n'y en a pas).");
        setValue(L.DESC_TEMPLATE_ANNOTATE_INSTRUCTIONS, "Ce que l'auteur veut faire examiner dans la partie (vide s'il n'a pas donné d'instructions).");
        setValue(L.DESC_TEMPLATE_OUTPUT_FORMAT, "Comment on demande au modèle d'écrire sa réponse ; dépend de la façon dont les notes sont demandées.");
        setValue(L.DESC_TEMPLATE_STORY_ANNOTATIONS, "Les notes de l'auteur sur des passages de l'histoire présents dans le prompt et marqués pour être transmis au modèle, une par ligne (vide quand il n'y en a pas).");
        setValue(L.DESC_TEMPLATE_SELECTION, "Le texte de la partie que l'auteur a sélectionné pour le faire réécrire (vide quand toute la partie est réécrite). Distingue la réécriture d'un passage de celle de toute la partie.");
        setValue(L.DESC_TEMPLATE_SELECTION_BEFORE, "Le texte de la partie avant le passage sélectionné (seulement quand un passage est réécrit).");
        setValue(L.DESC_TEMPLATE_SELECTION_AFTER, "Le texte de la partie après le passage sélectionné (seulement quand un passage est réécrit).");
        setValue(L.DESC_TEMPLATE_INSTRUCTION_EXAMPLES, "Les instructions que l'auteur a données aux dernières parties de l'histoire, de la plus ancienne à la plus récente (vide quand il n'y en a pas).");
        setValue(L.DESC_TEMPLATE_IMPERSONATE_OUTLINE, "Le plan de l'histoire fourni par l'appelant, par exemple les données du chapitre en cours (vide s'il n'y en a pas).");
        setValue(L.DESC_TEMPLATE_IMPERSONATE_INSTRUCTIONS, "Ce sur quoi l'auteur veut que portent les instructions (vide s'il n'a pas donné d'orientation).");
        setValue(L.DESC_COMMAND_IMPERSONATE, "Fait rédiger au modèle les instructions du prochain tour à votre place et renvoie le texte. Coûte des jetons ; ne modifie rien.");
        setValue(L.DESC_COMMAND_IMPERSONATE_RETURN, "Les instructions rédigées du prochain tour");
        setValue(L.DESC_COMMAND_IMPERSONATE_INSTRUCTIONS_PARAM, "Ce sur quoi doivent porter les instructions ; vide continue l'histoire là où elle mène");
        setValue(L.DESC_COMMAND_IMPERSONATE_OUTLINE_PARAM, "Un plan de l'histoire pour le modèle (par exemple les données du chapitre en cours) ; vide pour aucun");
        setValue(L.DESC_COMMAND_IMPERSONATE_PROMPT_PARAM, "Un prompt de rédaction des instructions à utiliser à la place de celui du livre (un modèle) ; vide : celui du livre");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION, "Fait relire une partie de l'histoire au modèle et ajoute ses constats comme annotations. Coûte des jetons.");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION_LLM, "Fait relire au modèle la partie `part` (son identifiant ; n'importe quelle partie, pas seulement la dernière) comme le fait la fenêtre Annoter avec l'IA : il lit la partie, l'histoire avant elle (l'histoire plus ancienne sous forme de résumés) et après elle, le lore et le style du livre, et les notes que la partie a déjà, et trouve les erreurs de continuité, les contradictions avec le lore, les passages faibles et les écarts de style. Chaque constat devient une annotation (source AI) sur le passage cité par le modèle, ou sur toute la partie quand la citation n'est pas dans le texte, et est ajouté aussitôt. Le texte de l'histoire n'est pas modifié. `profile` est un profil de modèle de l'agent avec lequel relire au lieu du modèle de l'exécution. Lent, coûte des jetons. Renvoie l'identifiant de la partie et les nouvelles annotations (utilisez resolve-annotation, update-annotation ou delete-annotation sur celles avec lesquelles vous n'êtes pas d'accord).");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION_RETURN, "Objet JSON : l'identifiant de la partie, le nombre d'annotations créées et les annotations");
        setValue(L.DESC_COMMAND_INCLUDE_VERSIONS_PARAM, "Rechercher aussi dans les anciennes versions des parties (leur historique) ; false si omis");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT, "Définit combien de versions de chaque partie l'historique du livre garde, ou retire la limite du livre. Paramètre : maxVersions.");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT_LLM, "Définit le nombre maximal de versions d'une partie que l'historique des versions de ce livre garde (0 ne garde plus d'historique à partir de maintenant ; les versions existantes restent). Sans maxVersions, la limite du livre est retirée. Les limites des dossiers, de l'utilisateur et de l'administrateur s'appliquent toujours et la plus stricte l'emporte, le livre ne peut donc pas les relever. Modifie le livre ; ne supprime aucune version.");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT_RETURN, "JSON avec bookLimit (la limite de ce livre, null s'il n'en a pas), effectiveLimit (la limite qui compte, null s'il n'y en a pas) et setBy (BOOK, FOLDER, USER, PERMISSION ou NONE)");
        setValue(L.DESC_COMMAND_HISTORY_MAX_VERSIONS_PARAM, "Le nombre maximal de versions d'une partie à garder ; 0 ne garde pas d'historique. Omettez-le pour retirer la limite du livre");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS, "Montre ce qui a été fait sur le livre ouvert, jour par jour.");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS_LLM, "Ce qui a été fait sur le livre dans une plage de jours, jour par jour : jetons envoyés et générés, mots écrits, générés et supprimés, parties créées et supprimées, modifications, les minutes pendant lesquelles le livre a été ouvert, modifié, en génération et travaillé par des agents, et comment la taille du livre a changé. La plage est un nom (today, yesterday, last-7-days, last-30-days, this-month, all-time ; par défaut last-7-days), un jour (2026-03-14) ou deux jours (2026-03-01..2026-03-14) ; le côté est all (par défaut), me ou agents. Lecture seule.");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS_RETURN, "JSON avec les totaux de la plage et une ligne par jour");
        setValue(L.DESC_COMMAND_GET_STATISTICS, "Montre ce qui a été fait sur tous les livres, par jour ou par livre.");
        setValue(L.DESC_COMMAND_GET_STATISTICS_LLM, "Ce que l'auteur a fait sur tous ses livres dans une plage de jours : les totaux, et une ligne par jour ou par livre (by day, par défaut, ou by book ; les livres viennent dans l'ordre des mots reçus et ont un identifiant, un nom et un dossier, les livres disparus y figurent aussi, marqués deleted). Les chiffres sont les mêmes que pour un livre : jetons, mots, parties, modifications, minutes, croissance de la taille. La plage est un nom (today, yesterday, last-7-days, last-30-days, this-month, all-time ; par défaut last-7-days), un jour (2026-03-14) ou deux jours (2026-03-01..2026-03-14) ; le côté est all (par défaut), me ou agents. Les minutes des livres se chevauchent, les totaux sont le temps réel. Lecture seule.");
        setValue(L.DESC_COMMAND_GET_STATISTICS_RETURN, "JSON avec les totaux de la plage et une ligne par jour ou par livre");
        setValue(L.DESC_COMMAND_STATISTICS_RANGE_PARAM, "Les jours : today, yesterday, last-7-days, last-30-days, this-month, all-time, un jour (2026-03-14) ou deux jours (2026-03-01..2026-03-14)");
        setValue(L.DESC_COMMAND_STATISTICS_SIDE_PARAM, "Le travail de qui : all (par défaut), me ou agents");
        setValue(L.DESC_COMMAND_STATISTICS_BY_PARAM, "Comment lister : day (par défaut) ou book");
        setValue(L.DESC_TEMPLATE_EXPORT_AUTHOR, "Auteur du livre (vide s'il n'y en a pas).");
        setValue(L.DESC_TEMPLATE_EXPORT_QUOTED_TITLE, "Titre du livre, échappé pour être utilisé entre guillemets droits.");
        setValue(L.DESC_TEMPLATE_EXPORT_QUOTED_AUTHOR, "Auteur du livre, échappé pour être utilisé entre guillemets droits (vide s'il n'y en a pas).");
        setValue(L.DESC_TEMPLATE_EXPORT_LANGUAGE, "Code ISO 639-1 de la langue du livre.");
        setValue(L.DESC_TEMPLATE_EXPORT_DATE, "Date de l'export (YYYY-MM-DD).");
        setValue(L.DESC_MACRO_COMMAND, "Exécute une commande en lecture seule et insère sa réponse. Seules les commandes marquées pour les macros peuvent être utilisées, la réponse est gardée jusqu'à ce que la partie soit régénérée ou qu'une variante soit créée.");
        setValue(L.DESC_MACRO_CLOSEST_MESSAGE, "La partie de l'histoire la plus proche de celle en cours d'écriture ; avec un nombre, la n-ième plus proche (1 est la dernière partie). Vide s'il n'y a pas de telle partie.");
        setValue(L.DESC_MACRO_CLOSEST_SUMMARY, "Le résumé le plus proche de celui en cours d'écriture ; avec un nombre, le n-ième plus proche (1 est le plus récent). Vide s'il n'y a pas de tel résumé.");
        setValue(L.DESC_MACRO_CURRENT_MESSAGE, "Le texte de la partie que Régénérer ou une variante remplace. Vide pour une nouvelle partie.");
        setValue(L.DESC_MACRO_JOIN, "Joint les textes qui suivent le premier argument avec le premier argument comme séparateur. Les textes vides sont omis. Utilisez {{space}} ou {{newline}} pour un séparateur avec des espaces.");
        setValue(L.DESC_TEMPLATE_FACTS, "Les faits que les extensions connaissent sur l'histoire à cette partie, par exemple ce que sait chaque personnage (vide quand aucune extension n'en donne). Vérifiez la partie par rapport à eux : une contradiction est une erreur de continuité.");
        setValue(L.DESC_MACRO_EVAL, "true ou false pour une expression : comparaisons (== != < <= > >= ~= contains has) jointes par and, or, not et des parenthèses. Un texte s'écrit entre guillemets, un nom est une valeur du modèle (povCharacter, presentCharacters, une macro sans arguments), .nom est une variable locale et $nom une globale. Un nom inconnu ou une erreur de syntaxe donne Error. == compare exactement (les nombres par valeur), ~= ignore la casse, contains cherche un texte dans un texte, has cherche un élément dans une liste séparée par des virgules.");
        setValue(L.DESC_COMMAND_GET_PLANNED_SCENES, "Liste les scènes du planificateur du livre avec leurs détails et si elles sont écrites.");
        setValue(L.DESC_COMMAND_GET_PLANNED_SCENES_LLM, "Liste les scènes que l'auteur a prévu d'écrire, dans l'ordre, avec leur numéro, titre, cadre de la scène, personnage du point de vue, personnages présents, instructions et si elles sont faites. Lisez-la avant d'ajouter des scènes pour ne pas en répéter une.");
        setValue(L.DESC_COMMAND_ADD_PLANNED_SCENE, "Ajoute une scène à la fin du planificateur.");
        setValue(L.DESC_COMMAND_ADD_PLANNED_SCENE_LLM, "Ajoute une scène à la fin du planificateur de l'auteur : un titre court et les détails de tour que l'auteur mettra dans le formulaire du nouveau tour quand il l'écrira (instructions, cadre de la scène, personnage du point de vue, personnages présents). L'auteur la voit aussitôt dans l'onglet Planificateur et peut la modifier ou la supprimer. Écrivez les instructions comme une instruction pour le modèle d'histoire, concrète et courte ; n'écrivez pas la scène elle-même.");
        setValue(L.DESC_COMMAND_UPDATE_PLANNED_SCENE, "Modifie le titre ou les détails de tour d'une scène planifiée.");
        setValue(L.DESC_COMMAND_UPDATE_PLANNED_SCENE_LLM, "Modifie une scène du planificateur : passez seulement ce qui doit changer, ce que vous omettez reste. Le texte passé remplace l'ancien. Le fait que la scène soit faite n'est pas modifié ici, voir set-planned-scene-done.");
        setValue(L.DESC_COMMAND_SET_PLANNED_SCENE_DONE, "Marque une scène planifiée comme écrite ou non écrite.");
        setValue(L.DESC_COMMAND_SET_PLANNED_SCENE_DONE_LLM, "Marque une scène du planificateur comme faite (écrite) ou non faite. Seule l'histoire de l'auteur décide qu'une scène est écrite : faites-le quand l'auteur le dit.");
        setValue(L.DESC_COMMAND_MOVE_PLANNED_SCENE, "Déplace une scène planifiée à une autre place de la liste.");
        setValue(L.DESC_COMMAND_MOVE_PLANNED_SCENE_LLM, "Déplace une scène du planificateur à la place donnée (1 est la première). Les autres scènes se décalent ; relisez la liste ensuite.");
        setValue(L.DESC_COMMAND_DELETE_PLANNED_SCENE, "Supprime une scène planifiée.");
